list_customer_groups.code:
const response = await client.customerGroups.listCustomerGroups({search_text: 'wholesale', status: 'active', limit: 50});
for (const customerGroup of response.map.customer_groups) {
    console.log(customerGroup.id, customerGroup.name, customerGroup.status);
}
console.log(response.map.pagination.total, response.map.pagination.has_next);

create_customer_group.code:
const response = await client.customerGroups.createCustomerGroup({
    customer_group: {
        name: 'Wholesale Partners',
        description: 'Trade accounts',
        status: 'active',
        purchase_preference: {
            minimum_purchase: {enabled: true, amount: 50},
            on_account_purchase: {
                enabled: true,
                max_purchase: {enabled: true, amount: 500},
                credit_limit: {enabled: true, amount: 1000},
                payment_terms: {enabled: true, terms: 'NET_30'},
            },
        },
        tax_configuration: {
            override_store_tax: true,
            tax_exempt: false,
            tax_message: 'Prices exclude GST',
            show_prices_with_tax_included: true,
            prices_entered_with_tax_included: false,
            base_price_rounding: 'up',
        },
        product_display: {
            overwrite_default: true,
            variation_display_type: 'enable_matrix_view',
            display_parent_image: true,
            activate_colour_variation_image: false,
            show_selected_variation_value: true,
            strike_through_out_of_stock: false,
            single_click_variation_loading: true,
            price_display_method: 'highest',
        },
    },
});
console.log(response.map.customer_group.id, response.map.customer_group.status);

get_customer_group.code:
const response = await client.customerGroups.getCustomerGroup(1234);
const customerGroup = response.map.customer_group;
console.log(customerGroup.name, customerGroup.status, customerGroup.customer_count);
for (const customer of customerGroup.customers) {
    console.log(customer.id, customer.first_name, customer.last_name, customer.email);
}

patch_customer_group.code:
const response = await client.customerGroups.patchCustomerGroup(1234, {
    customer_group: {status: 'inactive', purchase_preference: {minimum_purchase: {amount: 75}}},
});
const customerGroup = response.map.customer_group;
console.log(customerGroup.status, customerGroup.purchase_preference.minimum_purchase.amount);

